import{H as e,V as t,et as n,j as r}from"./chunks/framework.Cj2C9hRh.js";var i=JSON.parse(`{"title":"TS描述文件声明","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/ts/declaration-files.md","filePath":"frontend/ts/declaration-files.md"}`),a={name:`frontend/ts/declaration-files.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="ts描述文件声明" tabindex="-1">TS描述文件声明 <a class="header-anchor" href="#ts描述文件声明" aria-label="Permalink to “TS描述文件声明”">​</a></h1><p>TypeScript 作为 JavaScript 的超集，在开发过程中不可避免要引用其他第三方的 JavaScript 的库。虽然通过直接引用可以调用库的类和方法，但是却无法使用TypeScript 诸如类型检查等特性功能。为了解决这个问题，需要将这些库里的函数和方法体去掉后只保留导出类型声明，而产生了一个描述 JavaScript 库和模块信息的声明文件。通过引用这个声明文件，就可以借用 TypeScript 的各种特性来使用库文件了。</p><p>假如我们想使用第三方库，比如 jQuery等等</p><p>声明文件以 <strong>.d.ts</strong> 为后缀 如：<code>hello.d.ts</code></p><p>声明文件或模块的语法格式如下：<code>declare module Module_Name { }</code></p><p><strong>很多流行的第三方库的声明文件不需要我们定义了</strong></p><ul><li><p><a href="https://github.com/DefinitelyTyped/DefinitelyTyped/tree/master/types" target="_blank" rel="noreferrer">https://github.com/DefinitelyTyped/DefinitelyTyped/tree/master/types</a></p></li><li><p><a href="https://www.typescriptlang.org/dt/search?search=" target="_blank" rel="noreferrer">https://www.typescriptlang.org/dt/search?search=</a></p></li></ul>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};